            <div id="successMessage" class="success"></div>
          </form>

          <script>
            const currencyInputs = document.querySelectorAll('[data-currency="true"]');

            function formatCurrency(value) {
              // Remove all non-numeric characters except decimal point
              let numericValue = value.replace(/[^0-9.]/g, '');

              // Handle multiple decimal points
              const parts = numericValue.split('.');
              if (parts.length > 2) {
                numericValue = parts[0] + '.' + parts.slice(1).join('');
              }

              // Ensure only 2 decimal places
              if (numericValue.includes('.')) {
                const [integerPart, decimalPart] = numericValue.split('.');
                numericValue = integerPart + '.' + decimalPart.substring(0, 2);
              }

              // Convert to number and back to ensure valid format
              const num = parseFloat(numericValue);
              if (isNaN(num)) return '';

              // Format with commas and 2 decimal places
              return num.toLocaleString('en-US', {
                minimumFractionDigits: 2,
                maximumFractionDigits: 2
              });
            }

            function validateCurrency(value) {
              if (!value) return false;
              const numericValue = value.replace(/[^0-9.]/g, '');
              const num = parseFloat(numericValue);
              return !isNaN(num) && num >= 0;
            }

            currencyInputs.forEach(input => {
              input.addEventListener('blur', function() {
                if (this.value) {
                  this.value = formatCurrency(this.value);
                }
              });

              input.addEventListener('input', function() {
                const errorElement = document.getElementById(this.id + 'Error');
                if (errorElement) {
                  if (this.value && !validateCurrency(this.value)) {
                    errorElement.textContent = 'Please enter a valid currency amount';
                  } else {
                    errorElement.textContent = '';
                  }
                }
              });
            });

            document.getElementById('currencyForm').addEventListener('submit', function(e) {
              e.preventDefault();

              let isValid = true;
              currencyInputs.forEach(input => {
                if (!input.value) {
                  isValid = false;
                  const errorElement = document.getElementById(input.id + 'Error');
                  if (errorElement) {
                    errorElement.textContent = 'This field is required';
                  }
                } else if (!validateCurrency(input.value)) {
                  isValid = false;
                  const errorElement = document.getElementById(input.id + 'Error');
                  if (errorElement) {
                    errorElement.textContent = 'Please enter a valid currency amount';
                  }
                }
              });

              if (isValid) {
                const successMessage = document.getElementById('successMessage');
                successMessage.textContent = 'Form submitted successfully!';
              }
            });
          </script>
        </body>
      </html>
    `);
  });

